⟦vr:ax⟧.grid(which="minor", alpha=0.2)
⟦vr:ax⟧.set_title("Axis control tour: limits, major and minor locators")
⟦vr:ax⟧.set_xlabel("time (s) — ticks every 2 s")
⟦vr:ax⟧.set_ylabel("sensor output (V)")
